___CSS_LOADER_EXPORT___.push([module.id, `:root {
    --bg: #f4f4f4;
    --panel: #ffffff;
    --ink: #1d1d1d;
    --muted: #666;
    --border: #d7d7d7;
    --accent: #2c7be5;
    --canvas-bg: #ffffff;
}

.dark-mode {
    --bg: #0b1020;
    --panel: #141d2b;
    --ink: #edf3ff;
    --muted: #b7c5dd;
    --border: #2b3a4f;
    --accent: #0085f1;
    --canvas-bg: #0d1117;
}

* {
    box-sizing: border-box;
}

body {
    margin: 0;
    padding: 0px;
    font-family: Arial, sans-serif;

}

#root>div {
    background: var(--bg);
    color: var(--ink);
}

.panel {
    display: flex;
    flex-wrap: wrap;
    gap: 8px 12px;
    align-items: center;
    padding: 10px 12px;
    background: var(--panel);
    border: 1px solid var(--border);
    border-radius: 10px;
    margin: 0 auto 12px;
    width: 100%;
}

.control {
    display: flex;
    width: 100%;
    align-items: center;
    gap: 6px;
    font-size: 12px;
    color: var(--muted);
}

.control span {
    font-weight: 600;
    white-space: nowrap;
    width: 100%;
    /* width: 95px; */
}

.value {
    width: 70px;
    text-align: right;
    font-size: 11px;
    color: var(--ink);
    font-weight: 700;
    border: 1px solid var(--border);
    border-radius: 6px;
    padding: 3px 6px;
    height: 26px;
}

input[type='range'] {
    width: 100%;
    max-width: 120px;
    accent-color: var(--accent);
}

input[type='number'],
input[type='text'],
select {
    width: 80px;
    flex-shrink:0;
    height: 28px;
    border: 1px solid var(--border);
    border-radius: 6px;
    padding: 0 6px;
    color: var(--ink);
    background: var(--bg);

}

button {
    border: 0;
    background: var(--accent);
    color: white;
    border-radius: 6px;
    padding: 7px 12px;
    font-weight: 600;
    cursor: pointer;
}

.content {
    display: flex;
    flex-direction: row;
    gap: 12px;
    height: 100vh;
    padding: 12px;
}

.sidebar {
    /* width: auto; */
    display: flex;
    flex-direction: column;
    width: 410px;
}

.state-manager-panel {
    border-style: dashed;
    transition: border-color 0.15s ease, background 0.15s ease;
}

.state-manager-panel.drop-active {
    border-color: var(--accent);
    background: color-mix(in srgb, var(--accent) 12%, var(--panel));
}

.state-status {
    width: 100%;
    color: var(--muted);
    font-size: 12px;
}

.modal-backdrop {
    position: fixed;
    z-index: 1000;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(0, 0, 0, 0.55);
}

.state-modal {
    width: min(520px, calc(100vw - 32px));
    max-height: calc(100vh - 32px);
    overflow: auto;
    padding: 18px;
    border: 1px solid var(--border);
    border-radius: 10px;
    background: var(--panel);
    color: var(--ink);
    box-shadow: 0 12px 40px rgba(0, 0, 0, 0.35);
}

.state-modal h2 {
    margin-top: 0;
}

.modal-name {
    display: flex;
    align-items: center;
    gap: 8px;
}

.modal-name input {
    width: 100%;
}

.modal-actions {
    display: flex;
    justify-content: flex-end;
    gap: 8px;
    margin-top: 16px;
}

.state-load-modal {
    width: min(760px, calc(100vw - 32px));
}

.state-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 12px;
}

.state-card {
    display: flex;
    flex-direction: column;
    gap: 6px;
    min-width: 0;
    padding: 10px;
    border: 1px solid var(--border);
    border-radius: 8px;
}

.state-card img,
.state-thumbnail-placeholder {
    width: 100%;
    height: 120px;
    object-fit: scale-down;
    border: 1px solid var(--border);
    border-radius: 6px;
    background: var(--canvas-bg);
}

.state-thumbnail-placeholder {
    display: grid;
    place-items: center;
    color: var(--muted);
}

.state-card strong {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.state-card > span {
    color: var(--muted);
    font-size: 11px;
}

.state-card-actions {
    display: flex;
    gap: 6px;
}

.delete-button {
    background: #a43d3d;
}

.maincontent {
    display: flex;
    flex-direction: column;
    width: 100%;
    height: 100%;
}

.maincontent .panel {
    width: 100%;
}

.canvas-container {
    position: relative;
    width: 100%;
    height: 100%;
    background: var(--canvas-bg);
    border: 1px solid var(--border);
    border-radius: 10px;
}

.canvas-toolbar {
    position: absolute;
    top: 10px;
    left: 50%;
    transform: translateX(-50%);
    z-index: 20;
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 6px;
    border: 1px solid var(--border);
    border-radius: 8px;
    background: color-mix(in srgb, var(--panel) 90%, transparent);
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.25);
}

.canvas-toolbar-button {
    width: 30px;
    height: 30px;
    padding: 0;
    display: grid;
    place-items: center;
    font-size: 15px;
    line-height: 1;
    border-radius: 6px;
}

@media (max-width: 768px) {
    .content {
        flex-direction: column;
    }

    .sidebar {
        width: 100%;
    }
}

.warning {
    color: #a43d3d;
